    tourDesc4: 'તમારું મર્ચન્ટ એકાઉન્ટ ઓળખવા માટે તમારો નોંધાયેલ ૧૦-આંકડાનો મોબાઇલ નંબર અહીં દાખલ કરો.',
    tourTitle5: 'પાસવર્ડ દાખલ કરો',
    tourDesc5: 'તમારો સુરક્ષિત એકાઉન્ટ પાસવર્ડ લખો. ડેમો માટે, અમે સ્ટાન્ડર્ડ ઓળખપત્રો પહેલેથી ભરેલા છે.',
    tourTitle6: 'લોગિન કરવા આગળ વધો',
    tourDesc6: 'તમારા ઓળખપત્રોને પ્રમાણિત કરવા અને POS એપ્લિકેશન શરૂ કરવા માટે આ બટન પર ટેપ કરો.',
    tourTitle7: 'ડેશબોર્ડ ઝાંખી',
    tourDesc7: 'આ ટેબ તમારા સ્ટોરના આંકડા, વેચાણ સારાંશ, તાજેતરના ઓર્ડર અને ઝડપી પગલાં નિયંત્રણો દર્શાવે છે.',
    tourTitle8: 'POS બિલિંગ ટર્મિનલ',
    tourDesc8: 'આ તમારું મુખ્ય સેલ્સ પોઈન્ટ છે. ટેબલો પસંદ કરો, કેટેગરીઝ પર ટેપ કરો અને ગ્રાહકોના ઓર્ડર આપવા માટે આઇટમ્સ ઉમેરો.',
    tourTitle9: 'ટેબલ વ્યવસ્થાપન',
    tourDesc9: 'રેસ્ટોરન્ટના ટેબલોનું સંચાલન કરો, તેમની ઓક્યુપન્સી સ્થિતિ જુઓ અને સક્રિય ટેબલ કાર્ટ્સને સરળતાથી ટ્રેક કરો.',
    tourTitle10: 'PLU ક્વિક કેલ્ક્યુલેટર',
    tourDesc10: 'કુલ ગણતરી કરવા અથવા કિંમત લુકઅપ કી દ્વારા આઇટમ્સ શોધવા માટે આ અનુકૂળ કેલ્ક્યુલેટરનો ઉપયોગ કરો.',
    tourTitle11: 'મુખ્ય મેનુ નેવિગેશન',
    tourDesc11: 'સાઇડબાર ખોલવા માટે આ મેનુ આઇકોન પર ટેપ કરો. ત્યાંથી તમે સેટિંગ્સ, સ્ટાફ મેનેજમેન્ટ, પ્રિન્ટ લોગ્સ અને ખર્ચ ટ્રેકિંગને ઍક્સેસ કરી શકો છો.',
    tourTitle12: 'વેચાણ ટ્રેકિંગ',
    tourDesc12: 'તમારા વાસ્તવિક સમયના કુલ વેચાણ પર નજર રાખો. ચુકવણીઓની પુષ્ટિ થતાં જ આ આપમેળે અપડેટ થાય છે.',
    tourTitle13: 'તાજેતરના ઓર્ડર્સ',
    tourDesc13: 'આ વિભાગ તમારા નવીનતમ ઓર્ડર દર્શાવે છે. તમે રસીદો પ્રિન્ટ કરી શકો છો, તેને વ્હોટ્સએપ પર મોકલી શકો છો અથવા ઓર્ડર વિગતો જોઈ શકો છો.',
    tourTitle14: 'સાઇડબાર ડ્રોઅર ખોલો',
    tourDesc14: 'નેવિગેશન ડ્રોઅર ખોલવા માટે મેનુ આઇકોન પર ટેપ કરો. આ તે જગ્યા છે જ્યાં તમે સેટિંગ્સ ઍક્સેસ કરી શકો છો, અહેવાલો ચકાસી શકો છો અને સ્ટાફનું સંચાલન કરી શકો છો.',
    tourTitle15: 'ટેબલ પસંદગી',
    tourDesc15: 'ડાઇન-ઇન ઓર્ડર માટે, તમે તેમના વ્યક્તિગત બિલ અને ઓક્યુપાઈડ સ્થિતિને ટ્રેક કરવા માટે અહીં સક્રિય ટેબલ પસંદ કરી શકો છો.',
    tourTitle16: 'ઉમેરવા માટે પ્રોડક્ટ પસંદ કરો',
    tourDesc16: 'આ ગ્રીડ સૂચિમાંની કોઈપણ પ્રોડક્ટ આઇટમ પર ટેપ કરીને તેને તમારા વર્તમાન સક્રિય કાર્ટમાં ઉમેરો.',
    tourDesc17: 'તમે કાર્ટમાં ઉમેરેલી બધી આઇટમ્સની સમીક્ષા કરો, તેમની માત્રા ગોઠવો અથવા જરૂર પડે તો તેમને દૂર કરો.',
    tourDesc18: 'ઓર્ડર આપતા પહેલા તમામ પસંદ કરેલી આઇટમ્સ અને એડઓન્સ માટે ગણતરી કરેલી કુલ કિંમત જુઓ.',
    tourDesc19: 'ચેકઆઉટ શીટ પર આગળ વધવા, ગ્રાહકની વિગતો દાખલ કરવા અને ચુકવણીને અંતિમ સ્વરૂપ આપવા માટે પે બટન પર ટેપ કરો.',
    tourTitle20: 'ગ્રાહકની વિગતો દાખલ કરો',
    tourDesc20: 'આ ઓર્ડર સાથે લિંક કરવા માટે વૈકલ્પિક રીતે નામ/ફોન દ્વારા હાલના ગ્રાહકો શોધો અથવા નવી વિગતો દાખલ કરો.',
    tourTitle21: 'પુષ્ટિ કરો અને ચૂકવો',
