    tourTitle9: 'टेबल व्यवस्थापन',
    tourDesc9: 'रेस्टॉरंट टेबल व्यवस्थापित करा, त्यांची व्याप्ती स्थिती पहा आणि सक्रिय टेबल कार्ट सहजपणे ट्रॅक करा.',
