    tourDesc17: 'कार्टमध्ये जोडलेल्या सर्व आयटमचे पुनरावलोकन करा, त्यांचे प्रमाण समायोजित करा किंवा आवश्यकतेनुसार ते काढून टाका.',
    tourDesc18: 'ऑर्डर देण्यापूर्वी सर्व निवडक आयटम आणि अॅड-ऑन्ससाठी मोजलेली एकूण किंमत पहा.',
    tourDesc19: 'चेकआउट शीटवर जाण्यासाठी, ग्राहकाचे तपशील प्रविष्ट करण्यासाठी आणि पेमेंट पूर्ण करण्यासाठी पे बटणावर टॅप करा.',
