    tourDesc12: 'ਆਪਣੀ ਰੀਅਲ-ਟਾਈਮ ਕੁੱਲ ਵਿਕਰੀ \'ਤੇ ਨਜ਼ਰ ਰੱਖੋ। ਭੁਗਤਾਨ ਦੀ ਪੁਸ਼ਟੀ ਹੋਣ \'ਤੇ ਇਹ ਆਪਣੇ ਆਪ ਅਪਡੇਟ ਹੋ ਜਾਂਦਾ ਹੈ।',
    tourTitle13: 'ਹਾਲੀਆ ਆਰਡਰ',
    tourDesc13: 'ਇਹ ਭਾਗ ਤੁਹਾਡੇ ਨਵੀਨਤਮ ਆਰਡਰ ਦਿਖਾਉਂਦਾ ਹੈ। ਤੁਸੀਂ ਰਸੀਦਾਂ ਪ੍ਰਿੰਟ ਕਰ ਸਕਦੇ ਹੋ, ਉਹਨਾਂ ਨੂੰ ਵਟਸਐਪ \'ਤੇ ਭੇਜ ਸਕਦੇ ਹੋ, ਜਾਂ ਆਰਡਰ ਦੇ ਵੇਰਵੇ ਦੇਖ ਸਕਦੇ ਹੋ।',
    tourTitle14: 'ਸਾਈਡਬਾਰ ਡਰਾਅਰ ਖੋਲ੍ਹੋ',
    tourDesc14: 'ਨੇਵੀਗੇਸ਼ਨ ਡਰਾਅਰ ਖੋਲ੍ਹਣ ਲਈ ਮੀਨੂ ਆਈਕਨ \'ਤੇ ਟੈਪ ਕਰੋ। ਇਹ ਉਹ ਥਾਂ ਹੈ ਜਿੱਥੇ ਤੁਸੀਂ ਸੈਟਿੰਗਾਂ ਤੱਕ ਪਹੁੰਚ ਸਕਦੇ ਹੋ, ਰਿਪੋਰਟਾਂ ਦੀ ਜਾਂਚ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਸਟਾਫ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰ ਸਕਦੇ ਹੋ।',
    tourTitle15: 'ਟੇਬਲ ਦੀ ਚੋਣ',
    tourDesc15: 'ਡਾਇਨ-ਇਨ ਆਰਡਰਾਂ ਲਈ, ਤੁਸੀਂ ਉਹਨਾਂ ਦੇ ਵਿਅਕਤੀਗਤ ਬਿੱਲਾਂ ਅਤੇ ਕਬਜ਼ੇ ਦੀ ਸਥਿਤੀ ਨੂੰ ਟਰੈਕ ਕਰਨ ਲਈ ਇੱਥੇ ਸਰਗਰਮ ਟੇਬਲ ਚੁਣ ਸਕਦੇ ਹੋ।',
    tourTitle16: 'ਜੋੜਨ ਲਈ ਉਤਪਾਦ ਚੁਣੋ',
    tourDesc16: 'ਇਸ ਗਰਿੱਡ ਸੂਚੀ ਵਿੱਚ ਕਿਸੇ ਵੀ ਉਤਪਾਦ ਆਈਟਮ \'ਤੇ ਟੈਪ ਕਰਕੇ ਇਸਨੂੰ ਆਪਣੇ ਮੌਜੂਦਾ ਸਰਗਰਮ ਕਾਰਟ ਵਿੱਚ ਜੋੜੋ।',
    tourDesc17: 'ਕਾਰਟ ਵਿੱਚ ਜੋੜੀਆਂ ਗਈਆਂ ਸਾਰੀਆਂ ਚੀਜ਼ਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ, ਉਹਨਾਂ ਦੀ ਮਾਤਰਾ ਨੂੰ ਵਿਵਸਥਿਤ ਕਰੋ, ਜਾਂ ਲੋੜ ਅਨੁਸਾਰ ਉਹਨਾਂ ਨੂੰ ਹਟਾਓ।',
    tourDesc18: 'ਆਰਡਰ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਸਾਰੀਆਂ ਚੁਣੀਆਂ ਗਈਆਂ ਚੀਜ਼ਾਂ ਅਤੇ ਐਡ-ਆਨਾਂ ਲਈ ਗਣਨਾ ਕੀਤੀ ਕੁੱਲ ਕੀਮਤ ਦੇਖੋ।',
    tourDesc19: 'ਚੈੱਕਆਉਟ ਸ਼ੀਟ \'ਤੇ ਜਾਣ, ਗਾਹਕ ਦੇ ਵੇਰਵੇ ਦਰਜ ਕਰਨ ਅਤੇ ਭੁਗਤਾਨ ਨੂੰ ਅੰਤਿਮ ਰੂਪ ਦੇਣ ਲਈ ਪੇ ਬਟਨ \'ਤੇ ਟੈਪ ਕਰੋ।',
    tourTitle20: 'ਗਾਹਕ ਦੇ ਵੇਰਵੇ ਦਰਜ ਕਰੋ',
    tourDesc20: 'ਇਸ ਆਰਡਰ ਨਾਲ ਲਿੰਕ ਕਰਨ ਲਈ ਵਿਕਲਪਿਕ ਤੌਰ \'ਤੇ ਨਾਮ/ਫੋਨ ਦੁਆਰਾ ਮੌਜੂਦਾ ਗਾਹਕਾਂ ਦੀ ਖੋਜ ਕਰੋ ਜਾਂ ਨਵੇਂ ਵੇਰਵੇ ਦਰਜ ਕਰੋ।',
    tourTitle21: 'ਪੁਸ਼ਟੀ ਕਰੋ ਅਤੇ ਭੁਗਤਾਨ ਕਰੋ',
