    tourDesc23: 'ਪ੍ਰਿੰਟ ਸੰਰਚਨਾਵਾਂ, ਬਿੱਲਿੰਗ ਵਿਕਲਪਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਨ ਜਾਂ ਟੂਰ ਗਾਈਡ ਨੂੰ ਮੁੜ ਚਾਲੂ ਕਰਨ ਲਈ ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ।',
