    tourTitle4: 'মোবাইল নম্বর লিখুন',
    tourDesc4: 'আপনার মার্চেন্ট অ্যাকাউন্ট শনাক্ত করতে আপনার নিবন্ধিত ১০-সংখ্যার মোবাইল নম্বর এখানে লিখুন।',
    tourTitle5: 'পাসওয়ার্ড লিখুন',
    tourDesc5: 'আপনার সুরক্ষিত অ্যাকাউন্টের পাসওয়ার্ড লিখুন। ডেমোর জন্য, আমরা স্ট্যান্ডার্ড প্রমাণপত্রাদি আগে থেকেই পূরণ করে রেখেছি।',
    tourTitle6: 'লগইন চালিয়ে যান',
    tourDesc6: 'আপনার প্রমাণপত্রাদি যাচাই করতে এবং POS অ্যাপ্লিকেশনটি চালু করতে এই বোতামটিতে আলতো চাপুন।',
    tourTitle7: 'ড্যাশবোর্ড ওভারভিউ',
    tourDesc7: 'এই ট্যাবটি আপনার স্টোরের পরিসংখ্যান, বিক্রয়ের সারাংশ, সাম্প্রতিক অর্ডার এবং দ্রুত পদক্ষেপের নিয়ন্ত্রণ প্রদর্শন করে।',
    tourTitle8: 'POS বিলিং টার্মিনাল',
    tourDesc8: 'এটি আপনার প্রধান বিক্রয় কেন্দ্র। টেবিল নির্বাচন করুন, বিভাগগুলিতে আলতো চাপুন এবং গ্রাহকের অর্ডার দিতে আইটেম যুক্ত করুন।',
    tourTitle9: 'টেবিল ব্যবস্থাপনা',
    tourDesc9: 'রেস্তোরাঁর টেবিলগুলি পরিচালনা করুন, তাদের দখলের স্থিতি দেখুন এবং সক্রিয় টেবিল কার্টগুলি সহজেই ট্র্যাক করুন।',
    tourTitle10: 'PLU কুইক ক্যালকুলেটর',
    tourDesc10: 'মোট হিসাব করতে বা মূল্য লুকআপ কী এর মাধ্যমে আইটেমগুলি সন্ধান করতে এই সুবিধাজনক ক্যালকুলেটরটি ব্যবহার করুন।',
    tourTitle11: 'প্রধান মেনু নেভিগেশন',
    tourDesc11: 'সাইডবার খুলতে এই মেনু আইকনটিতে আলতো চাপুন। সেখান থেকে আপনি সেটিংস, কর্মী ব্যবস্থাপনা, প্রিন্ট লগ এবং খরচ ট্র্যাকিং অ্যাক্সেস করতে পারেন।',
    tourTitle12: 'বিক্রয় ট্র্যাকিং',
    tourDesc12: 'আপনার রিয়েল-টাইম মোট বিক্রয়ের উপর নজর রাখুন। পেমেন্ট নিশ্চিত হওয়ার সাথে সাথে এটি স্বয়ংক্রিয়ভাবে আপডেট হয়।',
    tourTitle13: 'সাম্প্রতিক অর্ডার',
    tourDesc13: 'এই বিভাগটি আপনার সর্বশেষ অর্ডারগুলি দেখায়। আপনি রসিদ প্রিন্ট করতে পারেন, হোয়াটসঅ্যাপে পাঠাতে পারেন, অথবা অর্ডারের বিবরণ দেখতে পারেন।',
    tourTitle14: 'সাইডবার ড্রয়ার খুলুন',
    tourDesc14: 'নেভিগেশন ড্রয়ার খুলতে মেনু আইকনটিতে আলতো চাপুন। এখান থেকে আপনি সেটিংস অ্যাক্সেস করতে পারেন, রিপোর্ট পরীক্ষা করতে পারেন এবং কর্মী পরিচালনা করতে পারেন।',
    tourTitle15: 'টেবিল নির্বাচন',
    tourDesc15: 'ডাইন-ইন অর্ডারের জন্য, আপনি তাদের ব্যক্তিগত বিল এবং দখলের স্থিতি ট্র্যাক করতে এখানে সক্রিয় টেবিল নির্বাচন করতে পারেন।',
    tourTitle16: 'যোগ করার জন্য পণ্য নির্বাচন করুন',
    tourDesc16: 'এই গ্রিড তালিকার যেকোনো পণ্য আইটেমের উপর আলতো চাপুন তা আপনার বর্তমান সক্রিয় কার্টে যুক্ত করতে।',
    tourDesc17: 'কার্টে যুক্ত করা সমস্ত আইটেম পর্যালোচনা করুন, তাদের পরিমাণ সামঞ্জস্য করুন, বা প্রয়োজন অনুসারে সেগুলি সরিয়ে দিন।',
    tourDesc18: 'অর্ডার দেওয়ার আগে সমস্ত নির্বাচিত আইটেম এবং অ্যাড-অন্সের জন্য গণনা করা মোট মূল্য দেখুন।',
    tourDesc19: 'চেকআউট শিটে যেতে, গ্রাহকের বিবরণ লিখতে এবং পেমেন্ট সম্পন্ন করতে পে বোতামে আলতো চাপুন।',
