    finishLabel: 'முடி',
    tourTitle1: 'பயன்பாட்டு முத்திரை',
    tourDesc1: 'பில்லிங் ஸ்பியருக்கு உங்களை வரவேற்கிறோம்! இது எங்கள் அதிகாரப்பூர்வ பயன்பாட்டு சின்னமாகும், இது உங்கள் ஆல்-இன்-ஒன் பிஓஎஸ் மையத்தை குறிக்கிறது.',
    tourTitle2: 'பில்லிங் ஸ்பியர் POS',
    tourDesc2: 'எங்கள் அதிநவீன பில்லிங் முறை பரிவர்த்தனைகள், இருப்பு மற்றும் மேஜைகளை திறம்பட நிர்வகிக்க உங்களுக்கு உதவுகிறது.',
    tourTitle3: 'ரேசர்பே கூட்டாளர்',
    tourDesc3: 'விரைவான கட்டணச் செலுத்தல்களுக்கு தடையற்ற டிஜிட்டல் மற்றும் அட்டை கட்டணங்களை ஆதரிக்க ரேசர்பேயுடன் ஒருங்கிணைக்கப்பட்டுள்ளது.',
    tourTitle4: 'கைபேசி எண்ணை உள்ளிடுக',
    tourDesc4: 'உங்கள் வணிகர் கணக்கை அடையாளம் காண உங்கள் பதிவு செய்யப்பட்ட 10 இலக்க மொபைல் எண்ணை இங்கே உள்ளிடவும்.',
    tourTitle5: 'கடவுச்சொல்லை உள்ளிடுக',
    tourDesc5: 'உங்கள் பாதுகாப்பான கணக்கு கடவுச்சொல்லை தட்டச்சு செய்க. டெமோவிற்காக, நாங்கள் நிலையான சான்றுகளை முன்பே நிரப்பியுள்ளோம்.',
    tourTitle6: 'உள்நுழைய தொடரவும்',
    tourDesc6: 'உங்கள் சான்றுகளை அங்கீகரித்து POS பயன்பாட்டைத் தொடங்க இந்த பொத்தானைத் தட்டவும்.',
    tourTitle7: 'டாஷ்போர்டு கண்ணோட்டம்',
    tourDesc7: 'இந்த தாவல் உங்கள் கடையின் புள்ளிவிவரங்கள், விற்பனை சுருக்கம், சமீபத்திய ஆர்டர்கள் மற்றும் விரைவான நடவடிக்கை கட்டுப்பாடுகளைக் காட்டுகிறது.',
    tourTitle8: 'POS பில்லிங் முனையம்',
    tourDesc8: 'இது உங்களின் முக்கிய விற்பனைப் புள்ளியாகும். வாடிக்கையாளர் ஆர்டர்களைச் செய்ய மேஜைகளைத் தேர்ந்தெடுத்து, வகைகளைத் தட்டி, பொருட்களைச் சேர்க்கவும்.',
    tourTitle9: 'மேஜை மேலாண்மை',
    tourDesc9: 'உணவக மேஜைகளை நிர்வகிக்கவும், அவற்றின் ஆக்கிரமிப்பு நிலையைப் பார்க்கவும், செயலில் உள்ள மேஜை வண்டிகளை எளிதாகக் கண்காணிக்கவும்.',
    tourTitle10: 'PLU விரைவான கால்குலேட்டர்',
    tourDesc10: 'மொத்த கணக்கீடுகளைச் செய்ய அல்லது விலை தேடல் விசைகள் மூலம் பொருட்களைத் தேட இந்த எளிய கால்குலேட்டரைப் பயன்படுத்தவும்.',
    tourTitle11: 'முதன்மை மெனு வழிசெலுத்தல்',
    tourDesc11: 'பக்கப்பட்டியைத் திறக்க இந்த மெனு ஐகானைத் தட்டவும். அங்கிருந்து நீங்கள் அமைப்புகள், ஊழியர் மேலாண்மை, அச்சு பதிவுகள் மற்றும் செலவு கண்காணிப்பு ஆகியவற்றை அணுகலாம்.',
    tourTitle12: 'விற்பனை கண்காணிப்பு',
    tourDesc12: 'உங்களின் நிகழ்நேர மொத்த விற்பனையைக் கண்காணிக்கவும். கட்டணங்கள் உறுதிசெய்யப்பட்டவுடன் இது தானாகவே புதுப்பிக்கப்படும்.',
    tourTitle13: 'சமீபத்திய ஆர்டர்கள்',
    tourDesc13: 'இந்தப் பிரிவு உங்களின் சமீபத்திய ஆர்டர்களைக் காட்டுகிறது. நீங்கள் ரசீதுகளை அச்சிடலாம், வாட்ஸ்அப்பிற்கு அனுப்பலாம் அல்லது ஆர்டர் விவரங்களை இங்கே பார்க்கலாம்.',
    tourTitle14: 'பக்கவாட்டு இழுப்பறையைத் திறக்கவும்',
    tourDesc14: 'வழிசெலுத்தல் இழுப்பறையைத் திறக்க மெனு ஐகானைத் தட்டவும். இங்குதான் நீங்கள் அமைப்புகளை அணுகலாம், அறிக்கைகளைச் சரிபார்க்கலாம் மற்றும் ஊழியர்களை நிர்வகிக்கலாம்.',
    tourTitle15: 'மேஜை தேர்வு',
    tourDesc15: 'டைன்-இன் ஆர்டர்களுக்கு, அவற்றின் தனிப்பட்ட பில்கள் மற்றும் ஆக்கிரமிக்கப்பட்ட நிலையைக் கண்காணிக்க செயலில் உள்ள மேஜைகளை இங்கே தேர்ந்தெடுக்கலாம்.',
    tourTitle16: 'சேர்க்க வேண்டிய தயாரிப்பைத் தேர்ந்தெடுக்கவும்',
    tourDesc16: 'உங்கள் தற்போதைய செயலில் உள்ள வண்டியில் சேர்க்க இந்த கட்ட அட்டவணையில் உள்ள எந்தவொரு தயாரிப்பு பொருளையும் தட்டவும்.',
    tourDesc17: 'வண்டியில் நீங்கள் சேர்த்த அனைத்து பொருட்களையும் மதிப்பாய்வு செய்யவும், அவற்றின் அளவை சரிசெய்யவும் அல்லது தேவைக்கேற்ப அவற்றை அகற்றவும்.',
    tourDesc18: 'ஆர்டர் செய்வதற்கு முன் தேர்ந்தெடுக்கப்பட்ட அனைத்து பொருட்கள் மற்றும் கூடுதல் பொருட்களுக்கான கணக்கிடப்பட்ட மொத்த விலையைப் பார்க்கவும்.',
    tourDesc19: 'பணமளிப்பு தாளுக்குச் செல்லவும், வாடிக்கையாளர் விவரங்களை உள்ளிடவும் மற்றும் கட்டணத்தை இறுதி செய்யவும் பே பொத்தானைத் தட்டவும்.',
    tourTitle20: 'வாடிக்கையாளர் விவரங்களை உள்ளிடவும்',
    tourDesc20: 'இந்த ஆர்டருடன் இணைக்க, பெயர்/தொலைபேசி மூலம் தற்போதுள்ள வாடிக்கையாளர்களைத் தேடலாம் அல்லது புதிய விவரங்களை உள்ளிடலாம்.',
    tourTitle21: 'உறுதிசெய்து செலுத்தவும்',
    tourDesc21: 'ஆர்டர் செய்யவும் மற்றும் வாடிக்கையாளருக்கான ரசீதை அச்சிடவும் இங்கே தட்டவும்.',
    tourDesc23: 'அச்சு உள்ளமைவுகள், பில்லிங் தேர்வுகள் அல்லது வழிகாட்டியை மீண்டும் தொடங்க அமைப்புகளைத் திறக்கவும்.',
    tourDesc24: 'உங்களுக்கு எப்போதாவது ஒரு நினைவூட்டல் தேவைப்பட்டால், இந்த ஊடாடும் வழிகாட்டியை மீண்டும் தொடங்க எப்போது வேண்டுமானாலும் இங்கே தட்டவும்.',
