    tourTitle4: 'మొబైల్ నంబర్ నమోదు చేయండి',
    tourDesc4: 'మీ వ్యాపారి ఖాతాను గుర్తించడానికి మీ నమోదిత 10 అంకెల మొబైల్ నంబర్‌ను ఇక్కడ నమోదు చేయండి.',
    tourTitle5: 'పాస్‌వర్డ్ నమోదు చేయండి',
    tourDesc5: 'మీ సురక్షిత ఖాతా పాస్‌వర్డ్‌ను టైప్ చేయండి. డెమో కోసం, మేము ప్రామాణిక ఆధారాలను ముందుగానే పూరించాము.',
    tourTitle6: 'లాగిన్ కొనసాగించండి',
    tourDesc6: 'మీ ఆధారాలను ప్రామాణీకరించడానికి మరియు POS అప్లికేషన్‌ను ప్రారంభించడానికి ఈ బటన్‌ను నొక్కండి.',
    tourTitle7: 'డాష్‌బోర్డ్ అవలోకనం',
    tourDesc7: 'ఈ ట్యాబ్ మీ స్టోర్ గణాంకాలు, అమ్మకాల సారాంశం, ఇటీవలి ఆర్డర్‌లు మరియు వేగవంతమైన చర్య నియంత్రణలను ప్రదర్శిస్తుంది.',
    tourTitle8: 'POS బిల్లింగ్ టెర్మినల్',
    tourDesc8: 'ఇది మీ ప్రధాన విక్రయ కేంద్రం. కస్టమర్ ఆర్డర్‌లను ఉంచడానికి టేబుల్‌లను ఎంచుకోండి, వర్గాలను నొక్కండి మరియు వస్తువులను జోడించండి.',
    tourTitle9: 'టేబుల్ నిర్వహణ',
    tourDesc9: 'రెస్టారెంట్ టేబుల్‌లను నిర్వహించండి, వాటి ఆక్యుపెన్సీ స్థితిని వీక్షించండి మరియు క్రియాశీల టేబుల్ కార్ట్‌లను సులభంగా ట్రాక్ చేయండి.',
    tourTitle10: 'PLU శీఘ్ర కాలిక్యులేటర్',
    tourDesc10: 'మొత్తాలను లెక్కించడానికి లేదా ధర శోధన కీల ద్వారా వస్తువులను వెతకడానికి ఈ సులభ కాలిక్యులేటర్‌ని ఉపయోగించండి.',
    tourTitle11: 'ప్రధాన మెనూ నావిగేషన్',
    tourDesc11: 'సైడ్‌బార్‌ను తెరవడానికి ఈ మెనూ చిహ్నాన్ని నొక్కండి. అక్కడ నుండి మీరు సెట్టింగ్‌లు, సిబ్బంది నిర్వహణ, ప్రింట్ లాగ్‌లు మరియు ఖర్చుల ట్రాకింగ్‌ను యాక్సెస్ చేయవచ్చు.',
    tourTitle12: 'అమ్మకాల ట్రాకింగ్',
    tourDesc12: 'మీ నిజ-సమయ మొత్తం అమ్మకాలను పర్యవేక్షించండి. చెల్లింపులు నిర్ధారించబడిన వెంటనే ఇది స్వయంచాలకంగా నవీకరించబడుతుంది.',
    tourTitle13: 'ఇటీవలి ఆర్డర్లు',
    tourDesc13: 'ఈ విభాగం మీ తాజా ఆర్డర్‌లను చూపుతుంది. మీరు రశీదులను ముద్రించవచ్చు, వాటిని వాట్సాప్‌కు పంపవచ్చు లేదా ఆర్డర్ వివరాలను ఇక్కడ చూడవచ్చు.',
    tourTitle14: 'సైడ్‌బార్ డ్రాయర్‌ని తెరవండి',
    tourDesc14: 'నావిగేషన్ డ్రాయర్‌ను తెరవడానికి మెనూ చిహ్నాన్ని నొక్కండి. ఇక్కడే మీరు సెట్టింగ్‌లను యాక్సెస్ చేయవచ్చు, నివేదికలను తనిఖీ చేయవచ్చు మరియు సిబ్బందిని నిర్వహించవచ్చు.',
    tourTitle15: 'టేబుల్ ఎంపిక',
    tourDesc15: 'డైన్-ఇన్ ఆర్డర్‌ల కోసం, వాటి వ్యక్తిగత బిల్లులు మరియు ఆక్యుపెన్సీ స్థితిని ట్రాక్ చేయడానికి మీరు ఇక్కడ క్రియాశీల టేబుల్‌లను ఎంచుకోవచ్చు.',
    tourTitle16: 'జోడించడానికి ఉత్పత్తిని ఎంచుకోండి',
    tourDesc16: 'మీ ప్రస్తుత క్రియాశీల కార్ట్‌కు జోడించడానికి ఈ గ్రిడ్ జాబితాలోని ఏదైనా ఉత్పత్తి వస్తువుపై నొక్కండి.',
    tourDesc17: 'కార్ట్‌లో మీరు జోడించిన అన్ని వస్తువులను సమీక్షించండి, వాటి పరిమాణాలను సర్దుబాటు చేయండి లేదా అవసరమైతే వాటిని తీసివేయండి.',
    tourDesc18: 'ఆర్డర్ చేయడానికి ముందు ఎంచుకున్న అన్ని వస్తువులు మరియు యాడ్-ఆన్‌ల కోసం లెక్కించిన మొత్తం ధరను వీక్షించండి.',
    tourDesc19: 'చెక్‌అవుట్ షీట్‌కి వెళ్లడానికి, కస్టమర్ వివరాలను నమోదు చేయడానికి మరియు చెల్లింపును ఖరారు చేయడానికి పే బటన్‌ను నొక్కండి.',
    tourTitle20: 'కస్టమర్ వివరాలను నమోదు చేయండి',
